import React, { useState, useEffect } from 'react';
import { useNavigate, Link, useSearchParams } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { getMyListings, updateProfile, getSaved } from '../services/api';
import {
  User, Mail, Phone, ShieldCheck, CheckCircle2, Heart,
  Building, Bell, HelpCircle, Info, LogOut,
  Camera, Plus, ChevronRight, X, AlertCircle
} from 'lucide-react';
import styles from './AccountPage.module.css';

const PRESET_AVATARS = [
  'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=200&auto=format&fit=crop&q=80',
  'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=200&auto=format&fit=crop&q=80',
  'https://images.unsplash.com/photo-1517841905240-472988babdf9?w=200&auto=format&fit=crop&q=80',
  'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=200&auto=format&fit=crop&q=80',
  'https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=200&auto=format&fit=crop&q=80',
  'https://images.unsplash.com/photo-1522075469751-3a6694fb2f61?w=200&auto=format&fit=crop&q=80',
  'https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=200&auto=format&fit=crop&q=80',
  'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=200&auto=format&fit=crop&q=80',
];

export default function AccountPage() {
  const { user, logout, updateUser } = useAuth();
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();

  const [activeTab, setActiveTab] = useState(searchParams.get('tab') || 'profile');
  const [listings, setListings] = useState([]);
  const [savedCount, setSavedCount] = useState(0);
  const [loading, setLoading] = useState(true);

  // Profile Edit State
  const [isEditing, setIsEditing] = useState(false);
  const [editName, setEditName] = useState('');
  const [editPhone, setEditPhone] = useState('');
  const [editPhoto, setEditPhoto] = useState('');
  const [savingProfile, setSavingProfile] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const [saveError, setSaveError] = useState('');

  // Info Modal (for Privacy, Support, About)
  const [infoModal, setInfoModal] = useState(null);

  // Sync tab with URL
  useEffect(() => {
    const tabParam = searchParams.get('tab');
    if (tabParam && tabParam !== activeTab) {
      setActiveTab(tabParam);
    }
  }, [searchParams, activeTab]);

  useEffect(() => {
    if (!user) {
      navigate('/login');
      return;
    }

    setEditName(user.name || '');
    setEditPhone(user.phone || '');
    setEditPhoto(user.photo || '');

    // Fetch user listings & saved count
    Promise.all([
      getMyListings().then(res => setListings(res.data.properties || [])).catch(() => []),
      getSaved().then(res => setSavedCount(res.data.results?.length || res.data.properties?.length || res.data.savedIds?.length || 0)).catch(() => 0),
    ]).finally(() => setLoading(false));
  }, [user, navigate]);

  const handleTabChange = (tab) => {
    setActiveTab(tab);
    setSearchParams(tab === 'profile' ? {} : { tab });
  };

  const handleSaveProfile = async (e) => {
    e.preventDefault();
    setSavingProfile(true);
    setSaveError('');
    setSaveSuccess(false);

    try {
      const res = await updateProfile({
        name: editName,
        phone: editPhone,
        photo: editPhoto,
      });

      if (res.data?.success && res.data.user) {
        updateUser(res.data.user);
        setSaveSuccess(true);
        setTimeout(() => {
          setIsEditing(false);
          setSaveSuccess(false);
        }, 1200);
      }
    } catch (err) {
      setSaveError(err.response?.data?.message || 'Failed to update profile. Please try again.');
    } finally {
      setSavingProfile(false);
    }
  };

  const handleLogout = () => {
    if (window.confirm('Are you sure you want to sign out of ProBridge?')) {
      logout();
      navigate('/');
    }
  };

  if (!user) return null;

  return (
    <div className={styles.pageWrap}>
      <div className={styles.container}>

        {/* ── Page Header ─────────────────────────────────────── */}
        <div className={styles.pageHeader}>
          <div>
            <h1 className={styles.pageTitle}>My Account</h1>
            <p className={styles.pageSubtitle}>Manage your profile, properties, saved homes and preferences</p>
          </div>
          <Link to="/post-property" className={styles.headerPostBtn}>
            <Plus size={16} />
            Post New Property
          </Link>
        </div>

        {/* ── Top Profile Card (Matches Mobile App AccountScreen) ─ */}
        <div className={styles.profileCard}>
          <div className={styles.profileMain}>
            <div className={styles.avatarContainer}>
              {user.photo ? (
                <img src={user.photo} alt={user.name} className={styles.avatarImg} />
              ) : (
                <div className={styles.avatarFallback}>
                  {user.name ? user.name[0].toUpperCase() : 'U'}
                </div>
              )}
              <button
                type="button"
                className={styles.avatarBadgeBtn}
                onClick={() => { setIsEditing(true); setActiveTab('profile'); }}
                title="Change Avatar"
              >
                <Camera size={14} />
              </button>
            </div>

            <div className={styles.profileMeta}>
              <div className={styles.nameRow}>
                <h2 className={styles.userName}>{user.name}</h2>
                <span className={styles.trustBadge}>
                  <CheckCircle2 size={13} className={styles.trustIcon} />
                  {user.status === 'trusted' || !user.status ? 'Trusted Account' : user.status}
                </span>
              </div>

              <div className={styles.profileContacts}>
                <span className={styles.contactItem}>
                  <Mail size={14} />
                  {user.email}
                </span>
                <span className={styles.contactItem}>
                  <Phone size={14} />
                  {user.phone ? `+91 ${user.phone}` : 'No phone linked'}
                </span>
                <span className={styles.roleTag}>
                  {user.role === 'admin' ? 'Administrator' : 'Verified Member'}
                </span>
              </div>
            </div>

            <button
              type="button"
              className={styles.editProfileBtn}
              onClick={() => { setIsEditing(o => !o); setActiveTab('profile'); }}
            >
              {isEditing ? 'Cancel Edit' : 'Edit Profile'}
            </button>
          </div>

          {/* Quick Stats Strip (Matches Mobile App) */}
          <div className={styles.statsStrip}>
            <button
              type="button"
              className={styles.statBox}
              onClick={() => navigate('/saved')}
            >
              <Heart size={18} className={styles.statIconHeart} />
              <div className={styles.statContent}>
                <span className={styles.statValue}>{savedCount}</span>
                <span className={styles.statLabel}>Saved Homes</span>
              </div>
            </button>

            <button
              type="button"
              className={styles.statBox}
              onClick={() => handleTabChange('listings')}
            >
              <Building size={18} className={styles.statIconBuilding} />
              <div className={styles.statContent}>
                <span className={styles.statValue}>{listings.length}</span>
                <span className={styles.statLabel}>My Listings</span>
              </div>
            </button>

            <div className={styles.statBox}>
              <ShieldCheck size={18} className={styles.statIconShield} />
              <div className={styles.statContent}>
                <span className={styles.statValue}>Active</span>
                <span className={styles.statLabel}>Buyer Inquiries</span>
              </div>
            </div>
          </div>
        </div>

        {/* ── Main Two-Column Layout ───────────────────────────── */}
        <div className={styles.accountLayout}>

          {/* Left Navigation Menu (Matches Mobile Menu Items) */}
          <aside className={styles.navSidebar}>
            <div className={styles.menuGroup}>
              <span className={styles.menuHeading}>Account Menu</span>

              <button
                type="button"
                className={`${styles.menuBtn} ${activeTab === 'profile' ? styles.menuBtnActive : ''}`}
                onClick={() => handleTabChange('profile')}
              >
                <div className={styles.menuLeft}>
                  <span className={styles.menuIconCircle}><User size={16} /></span>
                  <span>Personal Details</span>
                </div>
                <ChevronRight size={16} className={styles.chevron} />
              </button>

              <button
                type="button"
                className={`${styles.menuBtn} ${activeTab === 'listings' ? styles.menuBtnActive : ''}`}
                onClick={() => handleTabChange('listings')}
              >
                <div className={styles.menuLeft}>
                  <span className={styles.menuIconCircle}><Building size={16} /></span>
                  <span>My Listings ({listings.length})</span>
                </div>
                <ChevronRight size={16} className={styles.chevron} />
              </button>

              <Link to="/saved" className={styles.menuBtn}>
                <div className={styles.menuLeft}>
                  <span className={styles.menuIconCircle}><Heart size={16} /></span>
                  <span>Saved Properties</span>
                </div>
                <ChevronRight size={16} className={styles.chevron} />
              </Link>

              <button
                type="button"
                className={`${styles.menuBtn} ${activeTab === 'notifications' ? styles.menuBtnActive : ''}`}
                onClick={() => handleTabChange('notifications')}
              >
                <div className={styles.menuLeft}>
                  <span className={styles.menuIconCircle}><Bell size={16} /></span>
                  <span>Notifications</span>
                </div>
                <ChevronRight size={16} className={styles.chevron} />
              </button>
            </div>

            <div className={styles.menuGroup}>
              <span className={styles.menuHeading}>Security & Support</span>

              <button
                type="button"
                className={styles.menuBtn}
                onClick={() => setInfoModal('security')}
              >
                <div className={styles.menuLeft}>
                  <span className={styles.menuIconCircle}><ShieldCheck size={16} /></span>
                  <span>Privacy & Security</span>
                </div>
                <ChevronRight size={16} className={styles.chevron} />
              </button>

              <button
                type="button"
                className={styles.menuBtn}
                onClick={() => setInfoModal('support')}
              >
                <div className={styles.menuLeft}>
                  <span className={styles.menuIconCircle}><HelpCircle size={16} /></span>
                  <span>Help & Support</span>
                </div>
                <ChevronRight size={16} className={styles.chevron} />
              </button>

              <button
                type="button"
                className={styles.menuBtn}
                onClick={() => setInfoModal('about')}
              >
                <div className={styles.menuLeft}>
                  <span className={styles.menuIconCircle}><Info size={16} /></span>
                  <span>About ProBridge</span>
                </div>
                <ChevronRight size={16} className={styles.chevron} />
              </button>
            </div>

            {/* Logout button */}
            <button
              type="button"
              className={styles.logoutBtn}
              onClick={handleLogout}
            >
              <LogOut size={16} />
              <span>Log Out</span>
            </button>
          </aside>

          {/* Right Main Content Panel */}
          <main className={styles.contentMain}>

            {/* ── TAB: Profile Details & Inline Edit ── */}
            {activeTab === 'profile' && (
              <div className={styles.card}>
                <div className={styles.cardHeader}>
                  <div>
                    <h3 className={styles.cardTitle}>Personal Information</h3>
                    <p className={styles.cardDesc}>Your basic profile details linked with your mobile app and website account</p>
                  </div>
                  {!isEditing && (
                    <button
                      type="button"
                      className={styles.secondaryBtn}
                      onClick={() => setIsEditing(true)}
                    >
                      Edit Profile
                    </button>
                  )}
                </div>

                {saveSuccess && (
                  <div className={styles.successBanner}>
                    <CheckCircle2 size={18} />
                    Profile updated successfully!
                  </div>
                )}
                {saveError && (
                  <div className={styles.errorBanner}>
                    <AlertCircle size={18} />
                    {saveError}
                  </div>
                )}

                {isEditing ? (
                  <form onSubmit={handleSaveProfile} className={styles.editForm}>
                    <div className={styles.formRow}>
                      <label className={styles.formLabel}>Full Name</label>
                      <input
                        type="text"
                        className={styles.formInput}
                        value={editName}
                        onChange={(e) => setEditName(e.target.value)}
                        placeholder="Your full name"
                        required
                      />
                    </div>

                    <div className={styles.formRow}>
                      <label className={styles.formLabel}>Email Address</label>
                      <input
                        type="email"
                        className={`${styles.formInput} ${styles.inputDisabled}`}
                        value={user.email}
                        disabled
                        title="Email cannot be changed"
                      />
                      <span className={styles.inputHelp}>Email is verified and linked to your ProBridge credentials.</span>
                    </div>

                    <div className={styles.formRow}>
                      <label className={styles.formLabel}>Phone Number</label>
                      <input
                        type="tel"
                        className={styles.formInput}
                        value={editPhone}
                        onChange={(e) => setEditPhone(e.target.value)}
                        placeholder="10-digit mobile number"
                        maxLength={10}
                      />
                    </div>

                    <div className={styles.formRow}>
                      <label className={styles.formLabel}>Profile Photo URL</label>
                      <input
                        type="url"
                        className={styles.formInput}
                        value={editPhoto}
                        onChange={(e) => setEditPhoto(e.target.value)}
                        placeholder="https://example.com/photo.jpg"
                      />
                    </div>

                    {/* Quick Avatar Chooser */}
                    <div className={styles.presetSection}>
                      <label className={styles.formLabel}>Or Pick a Preset Avatar</label>
                      <div className={styles.avatarGrid}>
                        {PRESET_AVATARS.map((url, idx) => (
                          <button
                            key={idx}
                            type="button"
                            className={`${styles.presetBtn} ${editPhoto === url ? styles.presetBtnActive : ''}`}
                            onClick={() => setEditPhoto(url)}
                          >
                            <img src={url} alt={`Avatar option ${idx + 1}`} className={styles.presetThumb} />
                          </button>
                        ))}
                      </div>
                    </div>

                    <div className={styles.formActions}>
                      <button
                        type="submit"
                        className={styles.primaryBtn}
                        disabled={savingProfile}
                      >
                        {savingProfile ? 'Saving Changes…' : 'Save Changes'}
                      </button>
                      <button
                        type="button"
                        className={styles.cancelBtn}
                        onClick={() => {
                          setIsEditing(false);
                          setEditName(user.name || '');
                          setEditPhone(user.phone || '');
                          setEditPhoto(user.photo || '');
                        }}
                      >
                        Cancel
                      </button>
                    </div>
                  </form>
                ) : (
                  <div className={styles.detailsList}>
                    <div className={styles.detailRow}>
                      <span className={styles.detailKey}>Full Name</span>
                      <span className={styles.detailVal}>{user.name}</span>
                    </div>
                    <div className={styles.detailRow}>
                      <span className={styles.detailKey}>Email Address</span>
                      <span className={styles.detailVal}>{user.email}</span>
                    </div>
                    <div className={styles.detailRow}>
                      <span className={styles.detailKey}>Phone Number</span>
                      <span className={styles.detailVal}>
                        {user.phone ? `+91 ${user.phone}` : <span className={styles.mutedText}>Not provided</span>}
                      </span>
                    </div>
                    <div className={styles.detailRow}>
                      <span className={styles.detailKey}>Account Status</span>
                      <span className={styles.detailVal}>
                        <span className={styles.statusPill}>
                          ✓ {user.status || 'trusted'}
                        </span>
                      </span>
                    </div>
                    <div className={styles.detailRow}>
                      <span className={styles.detailKey}>Database Mode</span>
                      <span className={styles.detailVal}>MongoDB Atlas (Synchronized with Mobile App)</span>
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* ── TAB: My Listings ── */}
            {activeTab === 'listings' && (
              <div className={styles.card}>
                <div className={styles.cardHeader}>
                  <div>
                    <h3 className={styles.cardTitle}>My Property Listings</h3>
                    <p className={styles.cardDesc}>Properties you have submitted on ProBridge</p>
                  </div>
                  <Link to="/post-property" className={styles.primaryBtn}>
                    <Plus size={16} />
                    Post Property Free
                  </Link>
                </div>

                {loading ? (
                  <div className={styles.loadingBox}>Loading your listings…</div>
                ) : listings.length === 0 ? (
                  <div className={styles.emptyBox}>
                    <div className={styles.emptyIcon}>🏠</div>
                    <h4 className={styles.emptyTitle}>You haven't posted any properties yet</h4>
                    <p className={styles.emptyText}>Sell or rent your residential and commercial properties to thousands of verified buyers.</p>
                    <Link to="/post-property" className={styles.primaryBtn} style={{ marginTop: 14 }}>
                      Post Your First Property Free
                    </Link>
                  </div>
                ) : (
                  <div className={styles.listingsList}>
                    {listings.map((prop) => (
                      <div key={prop._id || prop.id} className={styles.listingCard}>
                        <img
                          src={prop.image || prop.images?.[0] || 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=400&q=70'}
                          alt={prop.title}
                          className={styles.listingImg}
                        />
                        <div className={styles.listingInfo}>
                          <div className={styles.listingTopRow}>
                            <h4 className={styles.listingTitle}>{prop.title}</h4>
                            <span className={`${styles.approvalBadge} ${styles['badge_' + (prop.approvalStatus || 'approved')]}`}>
                              {prop.approvalStatus || 'approved'}
                            </span>
                          </div>
                          <p className={styles.listingLocation}>{prop.location}, {prop.city}</p>
                          <div className={styles.listingPriceRow}>
                            <span className={styles.listingPrice}>₹ {prop.price}</span>
                            <span className={styles.listingTypeTag}>{prop.listingType} • {prop.buildingType}</span>
                          </div>
                        </div>
                        <div className={styles.listingActions}>
                          <Link to={`/property/${prop._id || prop.id}`} className={styles.viewBtn}>
                            View Details →
                          </Link>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}

            {/* ── TAB: Notifications ── */}
            {activeTab === 'notifications' && (
              <div className={styles.card}>
                <div className={styles.cardHeader}>
                  <div>
                    <h3 className={styles.cardTitle}>Notifications</h3>
                    <p className={styles.cardDesc}>Updates about your properties, price drops and inquiries</p>
                  </div>
                </div>
                <div className={styles.notifItem}>
                  <div className={styles.notifIconWrap}>
                    <CheckCircle2 size={18} color="var(--primary)" />
                  </div>
                  <div>
                    <div className={styles.notifTitle}>Welcome to ProBridge!</div>
                    <div className={styles.notifBody}>Your account is connected to MongoDB Atlas. Your listings and saved homes stay synced across web and mobile.</div>
                    <span className={styles.notifTime}>Just now</span>
                  </div>
                </div>
              </div>
            )}

          </main>
        </div>

      </div>

      {/* ── Information Modal (Privacy, Support, About) ────── */}
      {infoModal && (
        <div className={styles.modalBackdrop} onClick={() => setInfoModal(null)}>
          <div className={styles.modalContent} onClick={(e) => e.stopPropagation()}>
            <div className={styles.modalHeader}>
              <h3 className={styles.modalTitle}>
                {infoModal === 'security' && 'Privacy & Security'}
                {infoModal === 'support' && 'Help & Support'}
                {infoModal === 'about' && 'About ProBridge'}
              </h3>
              <button
                type="button"
                className={styles.closeModalBtn}
                onClick={() => setInfoModal(null)}
              >
                <X size={18} />
              </button>
            </div>

            <div className={styles.modalBody}>
              {infoModal === 'security' && (
                <div>
                  <p><strong>Enterprise Security:</strong> All user credentials and personal communications are encrypted end-to-end using industry-standard bcrypt and JWT tokens.</p>
                  <p style={{ marginTop: 12 }}><strong>Data Protection:</strong> Your contact details and phone number are only shared with verified buyers after your explicit consent.</p>
                  <p style={{ marginTop: 12 }}><strong>Status:</strong> Your account currently holds <strong>Trusted Member</strong> verification standing.</p>
                </div>
              )}

              {infoModal === 'support' && (
                <div>
                  <p>Need assistance finding a property, publishing a listing, or verifying your account?</p>
                  <div className={styles.supportBox}>
                    <div><strong>Email:</strong> support@probridge.com</div>
                    <div style={{ marginTop: 6 }}><strong>Customer Helpline:</strong> 1800-419-7800 (Mon - Sat, 9 AM - 8 PM)</div>
                    <div style={{ marginTop: 6 }}><strong>Headquarters:</strong> Bangalore, Karnataka, India</div>
                  </div>
                </div>
              )}

              {infoModal === 'about' && (
                <div>
                  <h4>ProBridge Real Estate Platform</h4>
                  <p style={{ marginTop: 8 }}><strong>Version:</strong> v1.0.0 (Unified Mobile + Web Platform)</p>
                  <p style={{ marginTop: 8 }}><em>"We Connect World of Real Estate"</em></p>
                  <p style={{ marginTop: 8 }}>ProBridge is India's premier property discovery and management network, seamlessly connecting property owners, buyers, tenants and builders.</p>
                </div>
              )}
            </div>

            <div className={styles.modalFooter}>
              <button
                type="button"
                className={styles.primaryBtn}
                onClick={() => setInfoModal(null)}
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

    </div>
  );
}
